public void appendToXML(XmlElement _element)
{
    MobOrder						mobOrder;
    Map								postPromptCollectors;
    Map								additionalValues;
    XmlElement                      orderIdElement;
    XmlNodeList                     nodes;
    SetEnumerator                   sEnum;

    next appendToXML(_element);

    if (fieldsMap == null)
    {
        //no records returned, no need to go further
        return;
    }

    additionalValues = Map::create(fieldsMap.pack());
    sEnum = fieldsMap.keySet().getEnumerator();

    if(!fieldsMap.exists(TFMConstants::OrderBackendID()))
    {
        nodes = _element.getElementsByTagName(TFMConstants::OrderBackendID());
        if (nodes)
        {
            orderIdElement = nodes.item(0);
            fieldsMap.insert(TFMConstants::OrderBackendID(), orderIdElement.innerText());
        }
        else
        {
            return;
        }
    }

    mobOrder = MobOrder::constructFromBackendID(fieldsMap.lookup(TFMConstants::OrderBackendID()));
    postPromptCollectors = mobOrder.getPostPromptCollectors(fieldsMap.lookup(TFMConstants::OrderBackendID()));
    postPromptCollectors = MobPostOrderPromptOverride::addToCollectors(postPromptCollectors,classIdGet(mobOrder),'',true, additionalValues);
    while (sEnum && sEnum.moveNext())
    {
        //Leaving only added values in map
        additionalValues.remove(sEnum.current());
    }
    MobOrder::addPostPromptCollectors(postPromptCollectors,_element,additionalValues);
}
